/**
 * Writes the precomputed module-raised approval scenario steps (development seed only).
 *   npm run seed:approval-steps
 * Re-run after changing the master or scheme seeds; test 119 fails while the file is out of date.
 */
import { writeFileSync } from "node:fs";
import { buildModuleScenarioSteps } from "@/features/approvals/moduleScenarios";

const steps = buildModuleScenarioSteps();
const out = `/**
 * GENERATED by scripts/generate-approval-steps.ts. Do not edit by hand: run \`npm run seed:approval-steps\`.
 * Development seed only. Module-raised approval scenario steps (Phase 4 scanning configuration,
 * Phase 6 schemes, settlements and incentives), precomputed from the master and scheme seeds so the
 * approval seed does not build those seeds at start-up. See features/approvals/moduleScenarios.ts.
 */
import type { ModuleScenarioSteps } from "@/features/approvals/moduleScenarios";

export const MODULE_APPROVAL_STEPS: ModuleScenarioSteps = ${JSON.stringify(steps)};
`;
writeFileSync("src/data/mock/generated/approvalModuleSteps.ts", out);
console.log(`Wrote ${steps.scanConfig.length + steps.schemes.length + steps.wallet.length + steps.comms.length + steps.gifts.length + steps.risk.length} steps (${(out.length / 1024).toFixed(1)} kB)`);
